package com.nbi.ms.mapper;

import com.nbi.ms.dto.*;
import com.nbi.ms.model.Account;
import org.mapstruct.*;

// MapStruct generates the implementation at COMPILE time (plain Java, no reflection).
@Mapper(componentModel = "spring")
public interface AccountMapper {

    // entity → response DTO. passwordHash has no target field → never copied.
    AccountResponse toResponse(Account entity);

    // request DTO → entity. Map 'openingBalance' to 'balance'; ignore server fields.
    @Mapping(source = "openingBalance", target = "balance")
    @Mapping(target = "id", ignore = true)
    @Mapping(target = "passwordHash", ignore = true)
    @Mapping(target = "pendingHolds", ignore = true)
    Account toEntity(CreateAccountRequest request);

    // entity → detail DTO with a COMPUTED field.
    @Mapping(target = "availableBalance",
             expression = "java(entity.getBalance().subtract(entity.getPendingHolds()))")
    AccountDetailResponse toDetail(Account entity);
}
