package com.nbi.ms.service;

import com.nbi.ms.dto.*;
import com.nbi.ms.mapper.AccountMapper;
import com.nbi.ms.model.Account;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;

@Service
public class AccountService {
    private final Map<String, Account> repo = new HashMap<>();
    private final AccountMapper mapper; // injected generated mapper

    public AccountService(AccountMapper mapper) {
        this.mapper = mapper;
        repo.put("SAV2001", new Account("SAV2001", "Rajesh Kumar", "hash$secret",
                new BigDecimal("1000000.00"), new BigDecimal("50000.00")));
    }

    public AccountResponse create(CreateAccountRequest req) {
        Account entity = mapper.toEntity(req);          // DTO → entity (server fields ignored)
        entity.setId("ACC-" + UUID.randomUUID().toString().substring(0, 6));
        entity.setPasswordHash("hash$" + req.password().hashCode());
        entity.setPendingHolds(BigDecimal.ZERO);
        repo.put(entity.getId(), entity);
        return mapper.toResponse(entity);               // entity → DTO (no password)
    }

    public Optional<AccountDetailResponse> detail(String id) {
        return Optional.ofNullable(repo.get(id)).map(mapper::toDetail); // computed available
    }
}
