package com.nbi.ms.controller;

import com.nbi.ms.dto.*;
import com.nbi.ms.service.AccountService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import jakarta.validation.Valid;
import java.net.URI;

@RestController
@RequestMapping("/api/v1/accounts")
public class AccountController {

    private final AccountService service;
    public AccountController(AccountService service) { this.service = service; }

    @PostMapping
    public ResponseEntity<AccountResponse> create(@Valid @RequestBody CreateAccountRequest r) {
        AccountResponse resp = service.create(r);
        return ResponseEntity.created(URI.create("/api/v1/accounts/" + resp.id())).body(resp);
    }

    @GetMapping("/{id}/detail")
    public ResponseEntity<AccountDetailResponse> detail(@PathVariable String id) {
        return service.detail(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());
    }
}
